WITH RECURSIVE json_tree AS (
  SELECT shipment_overview::text as full_json FROM shipments LIMIT 1
)
SELECT substring(full_json, 1, 2000) as preview FROM json_tree;

SELECT DISTINCT jsonb_typeof(shipment_overview->'route') as route_type,
       jsonb_object_keys(shipment_overview->'route') as route_keys
FROM shipments, lateral jsonb_object_keys(shipment_overview->'route') LIMIT 10;
